export function interpolateArcRotateCamera(camera, scene, goal, signal, options) {
  const interpolationFactor = options?.interpolationFactor ?? 0.1;
  return new Promise((resolve, reject) => {
    const unsubscribe = scene.onBeforeRender(() => {
      if (signal?.aborted) { reject(); unsubscribe(); return; }
      if (goal.alpha !== undefined) camera.alpha += (goal.alpha - camera.alpha) * interpolationFactor;
      if (goal.beta !== undefined) camera.beta += (goal.beta - camera.beta) * interpolationFactor;
      if (goal.radius !== undefined) camera.radius += (goal.radius - camera.radius) * interpolationFactor;
      if (goal.target !== undefined) {
        camera.target.x += (goal.target.x - camera.target.x) * interpolationFactor;
        camera.target.y += (goal.target.y - camera.target.y) * interpolationFactor;
        camera.target.z += (goal.target.z - camera.target.z) * interpolationFactor;
      }
      if (nearGoal(camera, goal)) { resolve(); unsubscribe(); }
    });
  });
}
```

